/* FOCUS Phase A: preferences, quality budget and styleguide-only specimens. */
(()=>{'use strict';const root=document.documentElement,levels=['low','medium','high'];const motion=matchMedia('(prefers-reduced-motion:reduce)'),transparency=matchMedia('(prefers-reduced-transparency:reduce)');let choice=root.dataset.effects||'auto',tier=levels.indexOf(root.dataset.quality),raf=0,last=0,windowStart=0,frames=0,probe=[],bad=0,good=0,active=false,stable=false,batteryLow=false;const save=(key,value)=>{try{localStorage.setItem('ihawk:focus:'+key,value)}catch{}};
const constrained=()=>batteryLow||transparency.matches||matchMedia('(prefers-reduced-data:reduce)').matches||navigator.connection?.saveData;
function target(){if(constrained()||choice==='off')return 0;if(choice==='reduced')return 1;if(choice==='full')return 2;return(navigator.hardwareConcurrency||8)<=4||(navigator.deviceMemory||8)<=4||matchMedia('(pointer:coarse)').matches?1:2}
function renderQuality(){const output=document.getElementById('quality-output');if(output)output.textContent=levels[tier].toUpperCase();const reason=document.getElementById('quality-reason');if(reason)reason.textContent=constrained()?'Device preference limits effects.':motion.matches?'Reduced motion is enabled.':choice==='auto'?'Auto · may only step down.':'User setting: '+choice;}
function setTier(next){tier=Math.max(0,Math.min(2,next));root.dataset.quality=levels[tier];renderQuality()}
function stop(){cancelAnimationFrame(raf);active=false;last=0;windowStart=0;frames=0;root.dataset.motion='paused'}
function tick(t){if(document.hidden||!document.hasFocus()){stop();return}if(!last){last=t;windowStart=t;raf=requestAnimationFrame(tick);return}const delta=t-last;last=t;if(probe.length<45){probe.push(delta);if(probe.length===45){const avg=probe.reduce((a,b)=>a+b,0)/probe.length;setTier(Math.min(tier,avg>32?0:avg>22?1:tier));}}frames++;if(t-windowStart>=1000){const fps=frames*1000/(t-windowStart);frames=0;windowStart=t;if(fps<40){bad++;good=0}else{bad=0;good++}if(bad>=3){setTier(tier-1);bad=0}if(good>=20){stable=true;active=false;return}}raf=requestAnimationFrame(tick)}
function start(){root.dataset.motion=document.hidden||!document.hasFocus()?'paused':'active';if(active||stable||document.hidden||!document.hasFocus()||choice==='off')return;active=true;raf=requestAnimationFrame(tick)}
setTier(Math.max(0,tier));const effects=document.getElementById('foundation-effects');if(effects){effects.value=choice;effects.addEventListener('change',()=>{choice=effects.value;root.dataset.effects=choice;save('effects',choice);stop();probe=[];bad=0;good=0;stable=false;setTier(target());start()})}
let themeFrame1=0,themeFrame2=0;function switchTheme(theme){cancelAnimationFrame(themeFrame1);cancelAnimationFrame(themeFrame2);root.classList.add('theme-switching');root.dataset.theme=theme;root.style.colorScheme=theme;save('theme',theme);themeFrame1=requestAnimationFrame(()=>{themeFrame2=requestAnimationFrame(()=>root.classList.remove('theme-switching'))})}
const theme=document.getElementById('foundation-theme');if(theme){theme.value=root.dataset.theme;theme.addEventListener('change',()=>switchTheme(theme.value))}

document.querySelectorAll('[data-token]').forEach(row=>{const palette=row.closest('[data-palette]'),value=getComputedStyle(palette).getPropertyValue('--'+row.dataset.token).trim();row.querySelector('[data-color-value]').textContent=value});
document.querySelectorAll('[data-duration]').forEach(button=>button.addEventListener('click',()=>{const target=button.closest('.motion-demo').querySelector('.motion-target');target.getAnimations().forEach(a=>a.cancel());target.animate([{opacity:.25},{opacity:1}],{duration:motion.matches?Math.min(120,Number(button.dataset.duration)):Number(button.dataset.duration),easing:getComputedStyle(root).getPropertyValue('--ease-out').trim()})}));
transparency.addEventListener('change',()=>setTier(Math.min(tier,target())));navigator.connection?.addEventListener?.('change',()=>setTier(Math.min(tier,target())));motion.addEventListener('change',renderQuality);document.addEventListener('visibilitychange',()=>document.hidden?stop():start());window.addEventListener('blur',stop);window.addEventListener('focus',start);
if(navigator.getBattery)navigator.getBattery().then(battery=>{const update=()=>{batteryLow=!battery.charging&&battery.level<.2;if(batteryLow)setTier(0)};update();battery.addEventListener('levelchange',update);battery.addEventListener('chargingchange',update)}).catch(()=>{});start();
window.ihawkFocusFoundation={getQuality:()=>levels[tier],setTheme:switchTheme,setEffects(value){if(!['auto','full','reduced','off'].includes(value))return;choice=value;root.dataset.effects=choice;save('effects',choice);stop();probe=[];bad=0;good=0;stable=false;setTier(target());start();const select=document.getElementById('foundation-effects');if(select)select.value=value}};})();
